import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    for _ in range(t):
        try:
            n = int(next(iterator))
            m = int(next(iterator))
        except StopIteration:
            break

        sets = []
        for _ in range(m):
            v_i = int(next(iterator))
            current_set = set()
            for _ in range(v_i):
                current_set.add(int(next(iterator)))
            sets.append(current_set)

        # For each element x in X, compute its signature
        # Signature is a tuple indicating membership in each Si
        signatures = {}

        for x in range(n):
            sig = []
            for s in sets:
                if x in s:
                    sig.append(1)
                else:
                    sig.append(0)
            sig_tuple = tuple(sig)
            if sig_tuple not in signatures:
                signatures[sig_tuple] = []
            signatures[sig_tuple].append(x)

        # Each unique signature forms an atom
        # The number of atoms is the number of unique signatures
        # But wait, we need to verify that these atoms are valid.
        # An atom A must satisfy: for each Si, either A <= Si or A intersect Si = empty.
        # If all elements in A have the same signature, then for any Si:
        # - If the signature has 1 at position i, then all elements in A are in Si, so A <= Si.
        # - If the signature has 0 at position i, then no element in A is in Si, so A intersect Si = empty.
        # So yes, grouping by signature creates valid atoms.
        # And since we want to minimize k, and elements with different signatures 
        # cannot be in the same atom (because they would violate the condition for some Si),
        # the number of atoms is exactly the number of unique signatures.

        print(len(signatures))

if __name__ == "__main__":
    solve()
